package com.ctrlaltz.inventorymanager;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.io.File;
import java.net.URISyntaxException;
import java.net.URL;
import java.nio.file.Paths;

import static org.junit.jupiter.api.Assertions.assertEquals;

class ItemClassTest {
    Item item;
    Item itemFromFile;
    String imageString;
    File image;

    @BeforeEach
    void setUp() throws URISyntaxException {
        float testPrice = 1.99F;
        imageString = "";
        URL resourceURL = ItemClassTest.class.getClassLoader().getResource("test.jpg");
        image = Paths.get(resourceURL.toURI()).toFile();
        item = new Item(5, 1, "Test Item", "Test Brand", testPrice, "1 Year", 1, "New", imageString, "Test Description", "1234", "Australia", "26/10/2024", "26/10/2024");
        itemFromFile = new Item(5, 1, "Test Item", "Test Brand", testPrice, "1 Year", 1, "New", image, "Test Description", "1234", "Australia", "26/10/2024", "26/10/2024");
    }

    @Test
    void testImageString() {
        assertEquals(imageString, item.getPhotoAsString());
    }

    @Test
    void testImageFile() {
        assertEquals(imageString, itemFromFile.getPhotoAsString());
    }
}